import React, { useState, useEffect } from 'react';
import { 
  LineChart, TrendingUp, TrendingDown, DollarSign,
  Target, Zap, Sparkles
} from 'lucide-react';

const RevenueChart = ({ timeRange }) => {
  const [chartType, setChartType] = useState('line');
  const [revenueData, setRevenueData] = useState([]);
  const [forecastData, setForecastData] = useState([]);

  useEffect(() => {
    // Données simulées
    const baseData = {
      jour: [1200, 1350, 980, 1560, 1780, 1980, 2100, 1950, 1850, 2200, 2400, 2500],
      semaine: [8500, 9200, 7800, 10500, 12500, 14200, 15800],
      mois: [42000, 48000, 35000, 52000, 68000, 75000, 82000, 78000, 72000, 85000, 92000, 98000],
      année: [450000, 520000, 380000, 650000, 720000, 880000, 950000, 1020000, 880000, 760000, 650000, 720000]
    };

    const base = baseData[timeRange] || baseData.mois;
    setRevenueData(base);

    // Prévisions
    const forecast = base.map(value => value * (1 + (Math.random() * 0.3 - 0.1)));
    setForecastData(forecast);
  }, [timeRange]);

  const maxValue = Math.max(...[...revenueData, ...forecastData]);
  const totalRevenue = revenueData.reduce((a, b) => a + b, 0);
  const growth = ((revenueData[revenueData.length - 1] - revenueData[0]) / revenueData[0] * 100).toFixed(1);

  return (
    <div className="lg:col-span-2 bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
      {/* Header */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between mb-6">
        <div>
          <div className="flex items-center space-x-2 mb-2">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <DollarSign className="h-5 w-5 text-white" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Revenu et prévisions</h3>
              <p className="text-sm text-neutral-600 dark:text-neutral-400">Analyse des tendances de revenus</p>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-4 mt-4 lg:mt-0">
          <div className="text-right">
            <p className="text-3xl font-bold text-neutral-900 dark:text-white">
              €{totalRevenue.toLocaleString()}
            </p>
            <div className={`flex items-center ${growth >= 0 ? 'text-green-500' : 'text-red-500'}`}>
              {growth >= 0 ? <TrendingUp className="h-4 w-4 mr-1" /> : <TrendingDown className="h-4 w-4 mr-1" />}
              <span className="text-sm font-medium">{Math.abs(growth)}%</span>
            </div>
          </div>
        </div>
      </div>

      {/* Chart Toggle */}
      <div className="flex items-center space-x-2 mb-6">
        {['line', 'area', 'bar'].map((type) => (
          <button
            key={type}
            onClick={() => setChartType(type)}
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-all duration-300 ${
              chartType === type
                ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg'
                : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 hover:bg-neutral-200 dark:hover:bg-neutral-700'
            }`}
          >
            {type === 'line' ? 'Ligne' : type === 'area' ? 'Zone' : 'Barres'}
          </button>
        ))}
      </div>

      {/* Chart Container */}
      <div className="relative h-64">
        <div className="absolute inset-0">
          {/* Grid */}
          <div className="absolute inset-0">
            {[...Array(5)].map((_, i) => (
              <div 
                key={i}
                className="absolute left-0 right-0 border-t border-neutral-200 dark:border-neutral-800/30"
                style={{ bottom: `${i * 25}%` }}
              />
            ))}
          </div>

          {/* Lines */}
          <svg className="absolute inset-0 w-full h-full">
            {/* Revenue Line */}
            <path
              d={revenueData.map((value, i) => {
                const x = (i / (revenueData.length - 1)) * 100;
                const y = 100 - (value / maxValue) * 100;
                return `${i === 0 ? 'M' : 'L'} ${x}% ${y}%`;
              }).join(' ')}
              fill="none"
              stroke="url(#revenueGradient)"
              strokeWidth="3"
              strokeLinecap="round"
              strokeLinejoin="round"
            />

            {/* Forecast Line (dashed) */}
            <path
              d={forecastData.map((value, i) => {
                const x = (i / (forecastData.length - 1)) * 100;
                const y = 100 - (value / maxValue) * 100;
                return `${i === 0 ? 'M' : 'L'} ${x}% ${y}%`;
              }).join(' ')}
              fill="none"
              stroke="url(#forecastGradient)"
              strokeWidth="2"
              strokeDasharray="5,5"
              strokeLinecap="round"
            />

            {/* Dots for data points */}
            {revenueData.map((value, i) => {
              const x = (i / (revenueData.length - 1)) * 100;
              const y = 100 - (value / maxValue) * 100;
              return (
                <circle
                  key={i}
                  cx={`${x}%`}
                  cy={`${y}%`}
                  r="4"
                  fill="url(#revenueGradient)"
                  className="cursor-pointer hover:r-6 transition-all duration-300"
                />
              );
            })}

            {/* Gradients */}
            <defs>
              <linearGradient id="revenueGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#3b82f6" />
                <stop offset="100%" stopColor="#8b5cf6" />
              </linearGradient>
              <linearGradient id="forecastGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#10b981" stopOpacity="0.6" />
                <stop offset="100%" stopColor="#06b6d4" stopOpacity="0.6" />
              </linearGradient>
            </defs>
          </svg>
        </div>

        {/* Y-axis labels */}
        <div className="absolute -left-12 top-0 bottom-0 flex flex-col justify-between text-xs text-neutral-500">
          {[...Array(5)].map((_, i) => (
            <span key={i} className="-translate-y-1/2">
              €{Math.round((maxValue / 4) * (4 - i)).toLocaleString()}
            </span>
          ))}
        </div>
      </div>

      {/* X-axis labels */}
      <div className="flex justify-between mt-8 px-4">
        {timeRange === 'jour' 
          ? ['00h', '04h', '08h', '12h', '16h', '20h'].map((label, i) => (
              <span key={i} className="text-xs text-neutral-500">{label}</span>
            ))
          : timeRange === 'semaine'
          ? ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map((label, i) => (
              <span key={i} className="text-xs text-neutral-500">{label}</span>
            ))
          : ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Juin', 'Juil', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc'].map((label, i) => (
              <span key={i} className="text-xs text-neutral-500">{label}</span>
            ))
        }
      </div>

      {/* Legend and Stats */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between mt-8 pt-6 border-t border-neutral-200 dark:border-neutral-800">
        <div className="flex items-center space-x-6 mb-4 sm:mb-0">
          <div className="flex items-center space-x-2">
            <div className="h-3 w-3 rounded-full bg-gradient-to-r from-blue-500 to-purple-500"></div>
            <span className="text-sm text-neutral-600 dark:text-neutral-400">Revenu réel</span>
          </div>
          <div className="flex items-center space-x-2">
            <div className="h-3 w-3 rounded-full bg-gradient-to-r from-emerald-500/60 to-cyan-500/60"></div>
            <span className="text-sm text-neutral-600 dark:text-neutral-400">Prévision</span>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <div className="text-center">
            <div className="flex items-center justify-center space-x-1 text-green-500 mb-1">
              <Zap className="h-4 w-4" />
              <span className="text-sm font-medium">+{growth}%</span>
            </div>
            <p className="text-xs text-neutral-600 dark:text-neutral-400">Croissance</p>
          </div>
          <div className="text-center">
            <div className="flex items-center justify-center space-x-1 text-amber-500 mb-1">
              <Target className="h-4 w-4" />
              <span className="text-sm font-medium">98%</span>
            </div>
            <p className="text-xs text-neutral-600 dark:text-neutral-400">Objectif</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RevenueChart;
